def find_max_consecutive_ones(nums: list) -> int:
    max_count = 0
    current = 0
    for num in nums:
        if num == 1:
            current += 1
        else:
            if current > max_count:
                max_count = current
            current = 0
    if current > max_count:
        max_count = current
    return max_count
```

